// RPi 의 실제 LAN IP 를 global 에 둔다 (2026-08-28). 그전엔 '192.168.137.30'(이사 전 주소)이
// 센서 페이로드·배치 deviceInfo 에 박혀 서버로 갔다. 사용: global.get('systemIp')
const first = String(msg.payload || '').trim().split(/\s+/).filter(ip => /^\d+\.\d+\.\d+\.\d+$/.test(ip) && !ip.startsWith('100.') && !ip.startsWith('169.254.'))[0];
if (first) { global.set('systemIp', first); node.status({ fill: 'green', shape: 'dot', text: first }); }
else { node.warn('systemIp 판별 실패: ' + msg.payload); }
return null;
